n=22
out=[[4]*n for _ in range(n)]
# square objects: top row, left col, outer frame color, center fill, final left col
objs=[(1,0,8,2,0),(0,17,2,9,17),(5,5,8,3,5),(8,12,2,6,12),(12,17,2,7,17),(14,0,8,9,0)]
for top,_,frame,fill,left in objs:
    for dr in range(5):
        for dc in range(5):
            col=fill if 1<=dr<=3 and 1<=dc<=3 else frame
            out[top+dr][left+dc]=col
print('\n'.join(' '.join(map(str,row)) for row in out))
